 group:'M9 11a3 3 0 1 0 0-6 3 3 0 0 0 0 6Zm6-5a3 3 0 0 1 0 6M3 20v-2c0-5 12-5 12 0v2Zm14-7c3 0 4 2 4 5v2h-3',
 shield:'m12 3 8 3v6c0 4-4 7-8 9-4-2-8-5-8-9V6l8-3Zm-4 9 3 3 5-6',
 layers:'m12 3 10 5-10 5L2 8l10-5Zm-9 10 9 5 9-5M3 18l9 5 9-5',
 nodes:'M8 3h8v6H8V3Zm-5 13h7v5H3v-5Zm11 0h7v5h-7v-5ZM12 9v4M6.5 16v-3h11v3',
 activity:'M3 12h4l3-8 4 16 3-8h4',
